    segP(Bq, at(i, 0, Y1 - 0.2), at(i, 0.5, Y2 - 0.5), 0.5, 4); segP(Bq, at(i, 1, Y1 - 0.2), at(i, 0.5, Y2 - 0.5), 0.5, 4);
