  const plaza = {c:'#8d6e66', m:0, lk:0.45}, lobby = {c:'#3c3a39', glow:'#ffdcae', gk:0.55}, black = '#1c1b1c', red = {c:'#c22', glow:'#ff2a1a', gk:2.2};
