    for (const [a, b] of E){ const L = Math.hypot(b[0] - a[0], b[1] - a[1]), n = Math.max(2, Math.round(L/per)), ux = (b[0] - a[0])/L, uz = (b[1] - a[1])/L, nx = uz, nz = -ux;
      for (let k = 0; k < n; k++){ const s0 = k*L/n, sm2 = (k + 0.5)*L/n; P.push([a[0] + ux*s0 - nx*d + (k === 0 ? ux*d*0.6 : 0), a[1] + uz*s0 - nz*d + (k === 0 ? uz*d*0.6 : 0)]); P.push([a[0] + ux*sm2, a[1] + uz*sm2]); } }
