  const podC = {c:'#d2cab9', m:0, lk:0.6}, shop = {c:'#4b5358', glow:'#ffdcae', gk:0.6}, green = '#5b8743', light = {c:'#fffaf2', glow:'#fff7e6', gk:2.6};
  const GY = -1.1, WY = 6.6 + GY;                                   // local street level and the plaza-level walkways
