    prismP(B.p('#bdb5a5'), offP(P, 1.0), yt, yt + 0.25);
    { const Q = offP(P, 2.2); for (let i = 0; i < Q.length; i++){ const a = Q[i], b = Q[(i + 1) % Q.length]; if (Math.hypot(b[0] - a[0], b[1] - a[1]) > 6) segP(B.p(green), [a[0], yt + 0.6, a[1]], [b[0], yt + 0.6, b[1]], 0.6, 4); } }
    prismP(Pd, P, yt - 0.01, yt + 1.0, true);
