  const DECKS = [[-90, -9, 9.6, 18.3], [-15, -9, 18, 31.5], [11.5, 97, 11.3, 21.0], [11.5, 18, 20, 31], [123.5, 192, 9.2, 17.4]];
  for (const [x0, x1, z0, z1] of DECKS){
    abox(Pd, x0, x1, WY - 0.6, WY, z0, z1);
    for (const zz of [z0, z1]) abox(Pd, x0, x1, WY, WY + 1.1, zz - 0.15, zz + 0.15);
    for (let x = x0 + 4; x < x1 - 2; x += 10) for (const zz of [z0 + 1, z1 - 1]) abox(Pd, x - 0.35, x + 0.35, GY - 0.5, WY - 0.6, zz - 0.35, zz + 0.35);
    for (let x = x0 + 6; x < x1 - 4; x += 14){ const zc = (z0 + z1)/2; abox(B.p(green), x - 1.2, x + 1.2, WY, WY + 0.7, zc - 1.2, zc + 1.2); treeP(B, x, WY + 0.7, zc, 0.75, '#4f7d3a'); }
  }
